SELECT (SELECT count(*) FROM "Document") AS docs, (SELECT count(*) FROM "ClinicalEvent") AS events, (SELECT count(*) FROM "ClinicalEpisode") AS episodes, (SELECT count(*) FROM "EventRelationship") AS rels, (SELECT count(*) FROM "Conflict") AS conflicts, (SELECT count(*) FROM "TimelineGap") AS gaps, (SELECT count(*) FROM "EvidenceItem") AS evidence, (SELECT count(*) FROM "AuditLog") AS audit;
